def _day(s, i):
    if i == 0:
        return s
    for ru, en in DAYS.items():
        s = s.replace(ru, en)
    return s


def _role(tid):
    return ROLES[tid.split("-")[0]]


def _tid(tid):
    return f'<span class="tid {_role(tid)[1]}">{tid}</span>'


def build(i):
    """Return {key: html} for language index i (0 = ru, 1 = en)."""
    out = {}
    out["have"] = "".join(f"<li>{e(x[i])}</li>" for x in HAVE)
    out["ost"] = "".join(f'<tr><td><span class="oid">{o}</span> {e(t[i])}</td><td class="num"><b>{e(h)}</b></td></tr>' for o, t, h in OST)

    cards = []
    for hid, opp, (a, b, c), hyp, risk, metric, ok, kill, conf in HYPS:
        dl = "".join(f'<dt>{e(T[k][i])}</dt><dd{cls}>{e(v[i])}</dd>' for k, v, cls in
                     (("hy_risk", risk, ""), ("hy_metric", metric, ""), ("hy_ok", ok, ' class="ok"'), ("hy_kill", kill, ' class="kill"'), ("hy_conf", conf, "")))
        cards.append(f'<article class="hyp"><div class="hh"><span class="hid">{hid}</span><span class="seg">{opp} · ★</span>'
                     f'<span class="ice num" title="ICE = {a} × {b} × {c}">ICE {a}·{b}·{c} = {a * b * c}</span></div>'
                     f'<p class="ht">{e(hyp[i])}</p><dl>{dl}</dl></article>')
    out["hyps"] = "".join(cards)
    out["later"] = "".join(f'<tr><td><span class="hid">{h}</span></td><td>{e(t[i])}</td><td class="num">{a}·{b}·{c}&nbsp;=&nbsp;{a * b * c}</td></tr>'
                           for h, (a, b, c), t in LATER)

    out["effort"] = "".join(f'<tr><td class="num"><span class="sp">{sp}</span></td><td><b>{e(m[i])}</b></td><td>{e(g[i])}</td></tr>' for sp, m, g in EFFORT)

    out["backlog"] = "".join(f'<tr><td>{_tid(t)}</td><td>{e(ti[i])}</td><td>{e(h)}</td><td class="num"><span class="sp">{sp}</span></td>'
                             f'<td>{e(_day(w, i))}</td><td class="dep">{e(dep)}</td></tr>' for t, ti, h, sp, w, dep, *_ in TASKS)
    cap = []
    for k, (name, cls, sp, left) in ROLES.items():
        assert sum(t[3] for t in TASKS if t[0].startswith(k + "-")) == sp, k
        cap.append(f'<tr><td><span class="rdot {cls}"></span>{e(name[i])}</td><td class="num">{sp}</td><td class="num">16–24</td><td class="num">{left}</td></tr>')
    cap.append(f'<tr class="tot"><td>{e(T["total"][i])}</td><td class="num">{sum(t[3] for t in TASKS)}</td><td class="num">48–72</td><td></td></tr>')
    out["capacity"] = "".join(cap)

    groups = []
    for k, (name, cls, sp, _) in ROLES.items():
        items = []
        for t, ti, h, s, w, dep, story, why, done in TASKS:
            if not t.startswith(k + "-"):
                continue
            dl = "".join(f"<dt>{e(T[key][i])}</dt><dd>{e(v)}</dd>" for key, v in
                         (("js_story", story[i]), ("js_why", f"{s} SP — {why[i]}"), ("js_done", done[i]), ("js_dep", dep)))
            items.append(f'<details class="js"><summary>{_tid(t)}<span class="jt">{e(ti[i])}</span>'
                         f'<span class="jm num">{e(h)} · {e(_day(w, i))} · {s} SP</span></summary><dl>{dl}</dl></details>')
        groups.append(f'<div class="role"><h3><span class="rdot {cls}"></span>{e(name[i])} — {sp} SP</h3>{"".join(items)}</div>')
    out["stories"] = "".join(groups)

    out["week_head"] = "".join(f'<th><span class="rdot {c}"></span>{e(n[i])}</th>' for n, c, _, _ in ROLES.values())
    def chips(s):
        return " ".join(_tid(x.strip()) for x in s.split(","))
    out["week"] = "".join(f"<tr><td><b>{e(_day(d, i))}</b></td><td>{chips(a)}</td><td>{chips(b)}</td><td>{chips(c)}</td></tr>" for d, a, b, c in WEEK)

    out["risks"] = "".join(f"<tr><td><b>{e(r[i])}</b></td><td>{e(a[i])}</td></tr>" for r, a in RISKS)
    out["out"] = "".join(f"<li>{e(x[i])}</li>" for x in OUT)
    out["decisions"] = "".join(f'<li><span class="n">{n}</span><span>{e(x[i])}</span></li>' for n, x in enumerate(DECISIONS, 1))
    out["sources"] = "".join(f'<li><a href="{u}" target="_blank" rel="noopener">{e(t)}</a></li>' for t, u in SOURCES)
    return out
